INSERT INTO contenidos_educativos (titulo, categoria, descripcion, publicado) VALUES
('Conociendo el ciclo menstrual', 'Ciclo menstrual', 'El ciclo menstrual comprende cambios hormonales y físicos que ocurren de manera cíclica. Su duración y características pueden variar entre personas.', TRUE),
('Fases del ciclo', 'Educación', 'De forma general se describen las fases menstrual, folicular, ovulatoria y lútea. Esta información es educativa y no permite predecir con certeza la ovulación.', TRUE),
('Autocuidado y registro', 'Autocuidado', 'Registrar fechas y síntomas puede ayudar a conocer patrones personales. Ante dolor intenso, sangrado inusual o inquietudes, consulta a un profesional de salud.', TRUE);
